def run_backup(target_dir):
    safe_dir = os.path.abspath(target_dir)
    if not safe_dir.startswith(BACKUP_ROOT):
        raise ValueError("target_dir outside allowed backup root")
    subprocess.run(["tar", "-czf", "backup.tar.gz", safe_dir], shell=False, check=True)

def convert_image(filename):
    if not re.fullmatch(r"[\w.-]+", filename):
        raise ValueError("invalid filename")
    subprocess.call(["convert", filename, "output.png"], shell=False)

def read_file(base, filename):
    base_resolved = os.path.realpath(base)
    target = os.path.realpath(os.path.join(base_resolved, filename))
    if not target.startswith(base_resolved + os.sep):
        raise ValueError("path traversal attempt detected")
    return open(target).read()

API_KEY = os.environ.get("SERVICE_API_KEY")
if not API_KEY:
    raise RuntimeError("SERVICE_API_KEY environment variable is required")

def hash_password(pw):
    salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', pw.encode(), salt, 200_000)
    return salt.hex() + ':' + dk.hex()

def load_session(raw_bytes):
    data, signature = raw_bytes[:-32], raw_bytes[-32:]
    expected = hmac.new(SECRET_KEY, data, hashlib.sha256).digest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError("invalid session signature")
    return pickle.loads(data)
